<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import type { ColDef } from 'ag-grid-community'
import { ElMessage, ElMessageBox } from 'element-plus'
import AppDataGrid from '@/components/AppDataGrid.vue'
import KubernetesLabelDialog from '@/components/KubernetesLabelDialog.vue'
import { applyKubernetesObject, deleteKubernetesObject, getKubernetesObject, getKubernetesResourceTemplate, getKubernetesWorkloadStats, listKubernetesClusters, listKubernetesNamespaces, listKubernetesObjects, updateKubernetesObjectLabels, type KubernetesCluster, type KubernetesNamespace, type KubernetesObject } from '@/api/kubernetes'

type Option = { key: string; label: string; namespaced: boolean }
const groups: Record<string, { label: string; resources: Option[] }> = {
  network: { label: '网络管理', resources: [['services','Service'],['ingresses','Ingress'],['endpoints','Endpoints'],['networkpolicies','NetworkPolicy']].map(([key,label])=>({key,label,namespaced:true})) },
  config: { label: '配置管理', resources: [['configmaps','ConfigMap'],['secrets','Secret'],['resourcequotas','ResourceQuota'],['limitranges','LimitRange'],['horizontalpodautoscalers','HPA'],['poddisruptionbudgets','PDB']].map(([key,label])=>({key,label,namespaced:true})) },
  storage: { label: '存储管理', resources: [{key:'persistentvolumeclaims',label:'PVC',namespaced:true},{key:'persistentvolumes',label:'PV',namespaced:false},{key:'storageclasses',label:'StorageClass',namespaced:false}] },
  access: { label: '访问控制', resources: [{key:'serviceaccounts',label:'ServiceAccount',namespaced:true},{key:'roles',label:'Role',namespaced:true},{key:'rolebindings',label:'RoleBinding',namespaced:true},{key:'clusterroles',label:'ClusterRole',namespaced:false},{key:'clusterrolebindings',label:'ClusterRoleBinding',namespaced:false}] },
  workloads: { label: '工作负载管理', resources: [['deployments','Deployment'],['statefulsets','StatefulSet'],['daemonsets','DaemonSet'],['jobs','Job'],['cronjobs','CronJob'],['pods','Pod']].map(([key,label])=>({key,label,namespaced:true})) },
  namespaces: { label: '命名空间', resources: [{key:'namespaces',label:'Namespace',namespaced:false}] },
}
const route=useRoute(), group=computed(()=>groups[String(route.meta.kubernetesGroup)]||groups.network), isWorkload=computed(()=>String(route.meta.kubernetesGroup)==='workloads')
const clusters=ref<KubernetesCluster[]>([]), namespaces=ref<KubernetesNamespace[]>([]), clusterID=ref(0), resource=ref(''), namespace=ref(''), keyword=ref(''), rows=ref<KubernetesObject[]>([]), selected=ref<KubernetesObject[]>([])
const yamlDialog=ref(false), formDialog=ref(false), yaml=ref(''), form=ref({name:'',namespace:'default',replicas:1,image:'',schedule:'*/5 * * * *'})
const labelDialog=ref(false), labelSaving=ref(false), selectedLabelResource=ref<KubernetesObject|null>(null)
const workloadStats=ref({deployment:0,statefulSet:0,daemonSet:0,job:0,cronJob:0,pod:0})
const current=computed(()=>group.value.resources.find(x=>x.key===resource.value)||group.value.resources[0])
const stats=computed(()=>[
  {key:'deployments',label:'Deployment',count:workloadStats.value.deployment,tone:'blue'}, {key:'statefulsets',label:'StatefulSet',count:workloadStats.value.statefulSet,tone:'purple'},
  {key:'daemonsets',label:'DaemonSet',count:workloadStats.value.daemonSet,tone:'cyan'}, {key:'jobs',label:'Job',count:workloadStats.value.job,tone:'orange'},
  {key:'cronjobs',label:'CronJob',count:workloadStats.value.cronJob,tone:'pink'}, {key:'pods',label:'Pod',count:workloadStats.value.pod,tone:'green'},
])
async function loadClusters(){const {data}=await listKubernetesClusters();clusters.value=data.data;const id=Number(route.query.cluster_id||0);clusterID.value=id&&clusters.value.some(x=>x.id===id)?id:(clusters.value[0]?.id||0)}
async function loadNamespaces(){if(!clusterID.value||!isWorkload.value)return;const {data}=await listKubernetesNamespaces(clusterID.value);namespaces.value=data.data}
async function load(){if(!clusterID.value){rows.value=[];return}const [list,summary]=await Promise.all([listKubernetesObjects({cluster_id:clusterID.value,resource:resource.value,namespace:namespace.value,keyword:keyword.value}),isWorkload.value?getKubernetesWorkloadStats(clusterID.value,namespace.value):Promise.resolve(null)]);rows.value=list.data.data;if(summary){const x=summary.data.data;workloadStats.value={deployment:x.deployment,statefulSet:x.stateful_set,daemonSet:x.daemon_set,job:x.job,cronJob:x.cron_job,pod:x.pod}}}
function resourceRenderer(p:any){const row=p.data as KubernetesObject,wrap=document.createElement('div');wrap.className='resource-values';if(!row.requests?.cpu&&!row.requests?.memory&&!row.limits?.cpu&&!row.limits?.memory){wrap.textContent='-';return wrap}const add=(label:string,request?:string,limit?:string)=>{const line=document.createElement('div');line.className='resource-line';line.innerHTML=`<span class="resource-label">${label}:</span><code>${request||'-'}</code><i>/</i><code>${limit||'-'}</code>`;wrap.append(line)};add('CPU',row.requests?.cpu,row.limits?.cpu);add('Mem',row.requests?.memory,row.limits?.memory);return wrap}
function nameRenderer(p:any){const e=document.createElement('div');e.className='workload-name-cell';e.innerHTML=`<span><b>${p.value}</b><small>${p.data.namespace||'-'}</small></span>`;return e}
function labelRenderer(p:any){const labels=p.value||{},wrap=document.createElement('span'),icon=document.createElement('span'),badge=document.createElement('span');wrap.className='namespace-label-count';icon.className='namespace-label-icon';icon.textContent='◇';badge.className='namespace-label-badge';badge.textContent=String(Object.keys(labels).length);wrap.title='查看资源标签';wrap.onclick=()=>{selectedLabelResource.value=p.data;labelDialog.value=true};wrap.append(icon,badge);return wrap}
function shortImage(image:string){return image.split('/').pop()||image}
function imageRenderer(p:any){const images=(p.value||[]) as string[],wrap=document.createElement('div');wrap.className='workload-images';if(!images.length){wrap.textContent='-';return wrap}images.forEach(image=>{const tag=document.createElement('span');tag.className='workload-image';tag.textContent=shortImage(image);tag.onclick=async(event)=>{event.stopPropagation();await navigator.clipboard.writeText(image);ElMessage.success('完整镜像地址已复制')};wrap.append(tag)});return wrap}
function actionRenderer(p:any){const w=document.createElement('div');w.className='actions';const y=document.createElement('button'),d=document.createElement('button');y.className='icon-action';y.textContent='YAML';y.onclick=()=>editYAML(p.data);d.className='icon-action danger';d.textContent='删除';d.onclick=()=>remove(p.data);w.append(y,d);return w}
const base=()=>[{headerName:'序号',valueGetter:(p:any)=>p.node.rowIndex+1,width:62},{field:'name',headerName:'名称',cellRenderer:nameRenderer},{field:'labels',headerName:'标签',minWidth:100,cellRenderer:labelRenderer}] as ColDef[]
const imageColumn=(minWidth:number):ColDef=>({field:'images',headerName:'镜像',minWidth,cellRenderer:imageRenderer,tooltipValueGetter:p=>((p.value||[]) as string[]).join('\n')})
const columns=computed<ColDef[]>(()=>{const c=base();if(!isWorkload.value)c.push({field:'kind',headerName:'类型'},{field:'status',headerName:'状态'},{field:'age',headerName:'存活时间'});else if(['deployments','statefulsets'].includes(resource.value))c.push({field:'ready',headerName:'容器组'},{headerName:'Requests / Limits',cellRenderer:resourceRenderer},imageColumn(160));else if(resource.value==='daemonsets')c.push({field:'ready',headerName:'准备就绪'},imageColumn(180));else if(resource.value==='jobs')c.push({field:'ready',headerName:'完成'},{field:'status',headerName:'状态'},imageColumn(160));else if(resource.value==='cronjobs')c.push({field:'schedule',headerName:'调度规则'},{field:'last_schedule_time',headerName:'最后调度',minWidth:170},{field:'suspended',headerName:'暂停',valueFormatter:p=>p.value?'是':'否'});else c.push({field:'ready',headerName:'就绪'},{field:'status',headerName:'状态'},{field:'restarts',headerName:'重启次数'},{field:'pod_ip',headerName:'Pod IP'},{field:'node',headerName:'调度节点',minWidth:150});if(isWorkload.value)c.push({field:'age',headerName:'存活时间'});c.push({headerName:'操作',pinned:'right',width:150,cellRenderer:actionRenderer});return c.map(column=>{const action=column.headerName==='操作';return {...column,headerClass:action?'centered-grid-header':'left-grid-header',cellClass:action?'centered-grid-cell':'left-grid-cell'}})})
async function blankYAML(){const {data}=await getKubernetesResourceTemplate({cluster_id:clusterID.value,resource:resource.value,namespace:namespace.value});yaml.value=data.data.yaml;yamlDialog.value=true}
async function editYAML(row:KubernetesObject){const {data}=await getKubernetesObject({cluster_id:clusterID.value,resource:resource.value,namespace:row.namespace,name:row.name});yaml.value=data.data.yaml;yamlDialog.value=true}
async function saveYAML(){await applyKubernetesObject({cluster_id:clusterID.value,resource:resource.value,namespace:namespace.value,yaml:yaml.value});yamlDialog.value=false;ElMessage.success('保存成功');await load()}
function openForm(){form.value={name:'',namespace:namespace.value||'default',replicas:1,image:'',schedule:'*/5 * * * *'};formDialog.value=true}
function podTemplate(indent='  '){return `${indent}template:\n${indent}  metadata:\n${indent}    labels:\n${indent}      app: ${form.value.name}\n${indent}  spec:\n${indent}    restartPolicy: Always\n${indent}    containers:\n${indent}      - name: ${form.value.name}\n${indent}        image: ${form.value.image}\n`}
function formYAML(){
  const metadata=`metadata:\n  name: ${form.value.name}\n  namespace: ${form.value.namespace}\n`
  if(resource.value==='jobs')return `apiVersion: batch/v1\nkind: Job\n${metadata}spec:\n${podTemplate('  ').replace('restartPolicy: Always','restartPolicy: Never')}`
  if(resource.value==='cronjobs')return `apiVersion: batch/v1\nkind: CronJob\n${metadata}spec:\n  schedule: "${form.value.schedule}"\n  jobTemplate:\n    spec:\n${podTemplate('      ').replace('restartPolicy: Always','restartPolicy: OnFailure')}`
  const replicas=resource.value==='daemonsets'?'':`  replicas: ${form.value.replicas}\n`
  const serviceName=resource.value==='statefulsets'?`  serviceName: ${form.value.name}\n`:''
  return `apiVersion: apps/v1\nkind: ${current.value.label}\n${metadata}spec:\n${serviceName}${replicas}  selector:\n    matchLabels:\n      app: ${form.value.name}\n${podTemplate()}`
}
async function saveForm(){if(!form.value.name||!form.value.image){ElMessage.warning('请填写名称和镜像');return}yaml.value=formYAML();await saveYAML();formDialog.value=false}
const deleteOne=(row:KubernetesObject)=>deleteKubernetesObject({cluster_id:clusterID.value,resource:resource.value,namespace:row.namespace,name:row.name})
async function remove(row:KubernetesObject){await ElMessageBox.confirm(`确定删除 ${row.name}？`,'确认删除');await deleteOne(row);ElMessage.success('删除成功');await load()}
async function batchDelete(){await ElMessageBox.confirm(`确定删除选中的 ${selected.value.length} 项？`,'批量删除');await Promise.all(selected.value.map(deleteOne));selected.value=[];ElMessage.success('批量删除成功');await load()}
async function saveLabels(labels:Record<string,string>){if(!selectedLabelResource.value)return;labelSaving.value=true;try{await updateKubernetesObjectLabels({cluster_id:clusterID.value,resource:resource.value,namespace:selectedLabelResource.value.namespace,name:selectedLabelResource.value.name,labels});labelDialog.value=false;ElMessage.success('标签保存成功');await load()}finally{labelSaving.value=false}}
watch(group,()=>{resource.value=group.value.resources[0].key},{immediate:true});watch(clusterID,async()=>{namespace.value='';await loadNamespaces();await load()});watch([resource,namespace,keyword],load);loadClusters().then(async()=>{await loadNamespaces();await load()})
</script>

<template>
  <section class="page" :class="{'workload-page':isWorkload}">
    <div v-if="isWorkload" class="workload-types"><button v-for="item in stats" :key="item.key" :class="['type-card',item.tone,{active:resource===item.key}]" @click="resource=item.key"><span>{{item.label}}</span><strong>{{item.count}}</strong></button></div>
    <div class="toolbar"><div class="filters"><el-select v-model="clusterID" placeholder="选择集群"><el-option v-for="item in clusters" :key="item.id" :label="item.alias||item.name" :value="item.id"/></el-select><el-input v-model="keyword" :placeholder="isWorkload?'搜索工作负载名称…':'输入即搜索'" clearable/><el-select v-if="isWorkload" v-model="namespace" placeholder="所有命名空间" clearable filterable><el-option v-for="item in namespaces" :key="item.name" :label="item.name" :value="item.name"/></el-select><el-select v-else v-model="resource"><el-option v-for="item in group.resources" :key="item.key" :label="item.label" :value="item.key"/></el-select><el-input v-if="!isWorkload&&current.namespaced" v-model="namespace" placeholder="命名空间（全部）" clearable/></div><div class="toolbar-actions"><el-button v-if="selected.length" type="danger" plain @click="batchDelete">批量删除（{{selected.length}}）</el-button><el-button class="create-button secondary" @click="blankYAML">YAML 创建</el-button><el-button v-if="isWorkload&&resource!=='pods'" type="primary" class="create-button" @click="openForm">表单创建</el-button></div></div>
    <AppDataGrid class="grid" :row-data="rows" :column-defs="columns" :row-height="isWorkload ? 54 : undefined" pagination @selection-changed="selected=$event as KubernetesObject[]"/>
    <el-dialog v-model="yamlDialog" :title="`${current.label} YAML`" width="min(820px,72vw)"><el-input v-model="yaml" type="textarea" :rows="22" class="yaml"/><template #footer><el-button @click="yamlDialog=false">取消</el-button><el-button type="primary" @click="saveYAML">保存</el-button></template></el-dialog>
    <el-dialog v-model="formDialog" :title="`表单创建 ${current.label}`" width="min(620px,58vw)"><el-form label-width="90px"><el-form-item label="名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="命名空间" required><el-select v-model="form.namespace" filterable><el-option v-for="item in namespaces" :key="item.name" :label="item.name" :value="item.name"/></el-select></el-form-item><el-form-item v-if="['deployments','statefulsets'].includes(resource)" label="副本数"><el-input-number v-model="form.replicas" :min="1"/></el-form-item><el-form-item v-if="resource==='cronjobs'" label="调度规则" required><el-input v-model="form.schedule" placeholder="例如 */5 * * * *"/></el-form-item><el-form-item label="容器镜像" required><el-input v-model="form.image" placeholder="例如 nginx:latest"/></el-form-item></el-form><template #footer><el-button @click="formDialog=false">取消</el-button><el-button type="primary" @click="saveForm">创建</el-button></template></el-dialog>
    <KubernetesLabelDialog v-model="labelDialog" :title="`${selectedLabelResource?.name||''} 标签`" :labels="selectedLabelResource?.labels||{}" :saving="labelSaving" @save="saveLabels"/>
  </section>
</template>

<style scoped>
.page{height:100%;display:flex;flex-direction:column;gap:8px;min-width:0;min-height:0}.toolbar,.filters,.toolbar-actions{display:flex;align-items:center;gap:8px}.toolbar{justify-content:space-between}.filters{min-width:0;flex-wrap:wrap}.filters .el-select{width:170px}.filters .el-input{width:240px}.grid{flex:1;min-height:0}.workload-types{display:grid;grid-template-columns:repeat(6,minmax(105px,132px));justify-content:start;gap:6px}.type-card{display:flex;align-items:center;gap:6px;padding:7px 9px;border:1px solid var(--line);border-radius:8px;background:#fff;color:#717784;cursor:pointer}.type-card:hover,.type-card.active{border-color:var(--primary);background:color-mix(in srgb,var(--primary) 5%,white);color:var(--primary)}.type-card strong{margin-left:auto;font-size:17px;color:var(--text)}.type-icon{display:grid;place-items:center;width:27px;height:27px;border-radius:7px;font-weight:700;background:#edf3ff;color:#326ce5}.purple .type-icon{background:#f2efff;color:#7656d6}.cyan .type-icon{background:#eaf8fa;color:#16818d}.orange .type-icon{background:#fff5e5;color:#c57815}.pink .type-icon{background:#fff0f6;color:#be4f7d}.green .type-icon{background:#ebf8f0;color:#238d52}.create-button{min-width:96px}.create-button.secondary{border-color:var(--primary);color:var(--primary);background:#fff}.yaml :deep(textarea){font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px}.page :deep(.centered-grid-header .ag-header-cell-label){justify-content:center}.page :deep(.left-grid-header .ag-header-cell-label){justify-content:flex-start}.page :deep(.centered-grid-cell){display:flex;align-items:center;justify-content:center;text-align:center}.page :deep(.left-grid-cell){display:flex;align-items:center;justify-content:flex-start;overflow:hidden;text-align:left}.page :deep(.left-grid-cell .ag-cell-value){min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.page :deep(.workload-name-cell){display:flex;align-items:center;justify-content:flex-start;width:100%;height:100%;overflow:hidden;text-align:left}.page :deep(.workload-name-cell span){display:flex;min-width:0;flex-direction:column;line-height:18px}.page :deep(.workload-name-cell b),.page :deep(.workload-name-cell small){overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.page :deep(.workload-name-cell small){color:#9298a5}.page :deep(.workload-labels){color:#b48800;cursor:help}.page :deep(.actions){display:flex;align-items:center;justify-content:center;gap:6px;width:100%;height:100%}.page :deep(.icon-action){display:inline-flex;align-items:center;justify-content:center;height:26px;padding:0 8px;border:1px solid var(--primary);border-radius:7px;background:#fff;color:var(--primary);font-size:10px;line-height:1}.page :deep(.icon-action.danger){border-color:#ffb8b8;color:#f06464}@media(max-width:980px){.workload-types{grid-template-columns:repeat(3,minmax(105px,132px))}.toolbar{align-items:flex-start;flex-direction:column}.toolbar-actions{align-self:flex-end}}@media(max-width:620px){.workload-types{grid-template-columns:repeat(2,minmax(105px,132px))}.filters .el-input,.filters .el-select{width:100%}}
.workload-page :deep(.app-data-grid){--ag-background-color:#fff;--ag-odd-row-background-color:#fff;--ag-row-hover-color:#f7f8fb}.page :deep(.namespace-label-count){position:relative;display:inline-flex;width:30px;height:28px;align-items:center;justify-content:flex-start;color:#c99818;cursor:help}.page :deep(.namespace-label-icon){font-size:25px;line-height:1;transform:rotate(-45deg)}.page :deep(.namespace-label-badge){position:absolute;top:0;right:0;display:flex;min-width:16px;height:16px;align-items:center;justify-content:center;padding:0 3px;border-radius:8px;background:#d7a91f;color:#3d3107;font-size:9px;font-weight:700;line-height:16px}.page :deep(.workload-images){display:flex;min-width:0;max-width:100%;flex-direction:column;align-items:flex-start;justify-content:center;gap:2px;overflow:hidden}.page :deep(.workload-image){display:inline-flex;align-items:center;width:max-content;max-width:100%;height:18px;padding:0 7px;overflow:hidden;border-radius:999px;background:#f1f2f5;color:#555b67;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:10px;line-height:18px;text-overflow:ellipsis;white-space:nowrap;cursor:pointer}.page :deep(.resource-values){display:flex;flex-direction:column;justify-content:center;gap:0;width:100%;line-height:17px}.page :deep(.resource-line){display:grid;grid-template-columns:32px minmax(38px,auto) 8px minmax(38px,auto);align-items:center;column-gap:2px;white-space:nowrap}.page :deep(.resource-label){color:#8b909a;font-weight:600}.page :deep(.resource-line code){padding:0;background:transparent;color:#555b64;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:11px}.page :deep(.resource-line i){color:#d9dde5;font-style:normal;text-align:center}
.workload-types{padding-top:4px}.type-card > span{color:var(--text);font-weight:700}.type-card strong{font-weight:400}.type-card.active{border-color:var(--primary);background:var(--primary);box-shadow:0 4px 12px color-mix(in srgb,var(--primary) 22%,transparent)}.type-card.active>span,.type-card.active strong{color:#fff}
</style>
